658	            keys[4], keys[0], keys[5], keys[9], keys[2], keys[10]
659	        };
660	        size_t run_len = sizeof keys / sizeof keys[0];
661	        rbtree_t *t = rb_create(NULL);
662	        assert(t);
663	        for (size_t i = 0; i < run_len; i++) {
664	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
665	            assert(rb_size(t) == i + 1);
666	        }
667	
668	        assert(rb_validate(t) == 0);
669	
670	        collect_ctx_t collected = {0};
671	        rb_foreach(t, collect_cb, &collected);
672	        assert(collected.n == (int)run_len);
