            assert(rb_find(t, keys[i]) == (void *)keys[i]);

        rb_destroy(t);
        printf("ok - insert_rebalances_mixed_order\n");
    }
}

int main(void)
{
    test_rb_validate();
    test_rb_create();
    test_rb_insert();
    return 0;
}

